import hashlib,json,pathlib,tarfile,tempfile,os
import nibabel as nib
import numpy as np
from monai_workflow.runtime import run,validate_mask
root=pathlib.Path(tempfile.mkdtemp(prefix='monai-qualification-'))
with tarfile.open(pathlib.Path(os.environ['MONAI_PROVIDER_INPUT'])/'input.tar') as archive:
    expected={'image.nii.gz','label.nii.gz'}
    if set(archive.getnames())!=expected: raise ValueError('Qualification input inventory differs')
    for name in sorted(expected):
        member=archive.getmember(name)
        if not member.isfile(): raise ValueError('Qualification input must be a regular file')
        (root/name).write_bytes(archive.extractfile(member).read())
expected={'image.nii.gz':'78338b0015e5f4da8914e89147344cb9e0f6580237a654c70b3b24e85d87c9e2','label.nii.gz':'5df8d757e4ca841dbe0dbf37264cf4a4cc9a3fcc3f1a8889da266ea0c03ee156'}
for name,sha in expected.items():
    if hashlib.sha256((root/name).read_bytes()).hexdigest()!=sha: raise ValueError('Qualification input integrity differs')
output=pathlib.Path(os.environ['MONAI_PROVIDER_OUTPUT'])
result=run(root/'image.nii.gz',output,{},device='cuda')
pred=np.asarray(nib.load(output/'segmentation.nii.gz').dataobj)>0
label_image=nib.load(root/'label.nii.gz');label=np.asarray(label_image.dataobj)>0
original=nib.load(root/'image.nii.gz')
if label.shape!=original.shape or not np.allclose(label_image.affine,original.affine): raise ValueError('Label geometry differs')
dice=float(2*np.count_nonzero(pred & label)/(np.count_nonzero(pred)+np.count_nonzero(label)))
proof={'schema':'monai-qualification/v1','scope':'published validation-subset regression, not independent clinical accuracy','case':'MSD spleen_56','minimum_dice':0.90,'dice':dice,'reference_foreground_voxels':int(label.sum()),'predicted_foreground_voxels':int(pred.sum()),'input_sha256':expected['image.nii.gz'],'geometry_preserved':result['validation']['geometry_preserved'],'runtime':result['runtime'],'timings_s':result['timings_s']}
(output/'qualification.json').write_text(json.dumps(proof,indent=2)+'\n')
if not dice>=0.90: raise ValueError('Pinned pretrained MONAI regression Dice is below predeclared0.90; investigate model/pipeline')
print(json.dumps(proof))
